(1943546, 268063, 6349, '<td valign="top">My favorite photo in the challenge.  Simple pure and beautiful.  10 and favorite.</td>', 'My favorite photo in the challenge.  Simple pure and beautiful.  10 and favorite.', '2005-12-12 01:00:18.000000', NULL, 1),
(1943596, 266853, 43463, '<td valign="top">This winding magical pathway is illuminated with the soft glow of the candles that adorn the path. It really creates an invitation to the viewer to come follow the path around the bend as our eyes follow the trail of lights that curve off into the distance around the bend. Wonderful capture.</td>', 'This winding magical pathway is illuminated with the soft glow of the candles that adorn the path. It really creates an invitation to the viewer to come follow the path around the bend as our eyes follow the trail of lights that curve off into the distance around the bend. Wonderful capture.', '2005-12-12 01:09:06.000000', NULL, 1),
(1943613, 268070, 43463, '<td valign="top">Love the mood captured here. I get the feeling of a nighttime tour of an art gallery as we take a stroll with our guide who holds an old time candleholder. My only two critiques on this piece is that the glare off the painting on the right hand side is too distracting. Second is that details are lost on the handleholder which is too dark(which if it were much more visible would give a greater amount of viewers an impression of being in the 1800-early 1900''s time period) as well as the candle with flame which is too overexposed.</td>', 'Love the mood captured here. I get the feeling of a nighttime tour of an art gallery as we take a stroll with our guide who holds an old time candleholder. My only two critiques on this piece is that the glare off the painting on the right hand side is too distracting. Second is that details are lost on the handleholder which is too dark(which if it were much more visible would give a greater amount of viewers an impression of being in the 1800-early 1900''s time period) as well as the candle with flame which is too overexposed.', '2005-12-12 01:15:04.000000', NULL, 1),
(1943617, 268283, 33352, '<td valign="top">Find this hard to say if candlelight was used.</td>', 'Find this hard to say if candlelight was used.', '2005-12-12 01:16:19.000000', NULL, 1),
