(1946638, 266869, 21604, '<td valign="top">Very nice patterns created by the candle, good interpretation of the challenge.</td>', 'Very nice patterns created by the candle, good interpretation of the challenge.', '2005-12-13 09:06:29.000000', NULL, 1),
(1946641, 268055, 21604, '<td valign="top">I really like the imagination used in this shot.  Cool idea to use a slinky to create the interesting shadow pattern on the wall.  Like the choice of color cast too.</td>', 'I really like the imagination used in this shot.  Cool idea to use a slinky to create the interesting shadow pattern on the wall.  Like the choice of color cast too.', '2005-12-13 09:07:18.000000', NULL, 1),
(1946645, 268059, 21604, '<td valign="top">This is one of my favs of the challenge. I like the expression on the models face and the lighting is really good despite the difficulty with using candles, the candles themselves are a bit overexposed, but this doesn''t take anything away from the photo. 8</td>', 'This is one of my favs of the challenge. I like the expression on the models face and the lighting is really good despite the difficulty with using candles, the candles themselves are a bit overexposed, but this doesn''t take anything away from the photo. 8', '2005-12-13 09:09:16.000000', NULL, 1),
(1946647, 266891, 21604, '<td valign="top">This is too small and badly compressed to make a real judgement on.</td>', 'This is too small and badly compressed to make a real judgement on.', '2005-12-13 09:10:15.000000', NULL, 1),
(1946648, 268053, 49102, '<td valign="top">three beautiful candles which light mutually but the remainder is in the shade the effect which gives the rays of lights (thank you for the lens) emerges a little this black, limiting for clearness.</td>', 'three beautiful candles which light mutually but the remainder is in the shade the effect which gives the rays of lights (thank you for the lens) emerges a little this black, limiting for clearness.', '2005-12-13 09:10:34.000000', NULL, 1),
