INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1947494, 267871, 45933, '<td valign="top">WOW. this strikes my attention!  It is great how you clearly focused on the bullet.</td>', 'WOW. this strikes my attention!  It is great how you clearly focused on the bullet.', '2005-12-13 15:37:12.000000', NULL, 1),
(1947495, 266991, 45933, '<td valign="top">cool. this sort of reminds me of ice...with a warm orange tint.  beautiful reflection &amp; gradient of colors.</td>', 'cool. this sort of reminds me of ice...with a warm orange tint.  beautiful reflection & gradient of colors.', '2005-12-13 15:38:02.000000', NULL, 1),
(1947502, 267861, 45933, '<td valign="top">you captured the fire in a beautiful shimmering star-like manner. i love how you stacked the candles to add depth &amp; volume</td>', 'you captured the fire in a beautiful shimmering star-like manner. i love how you stacked the candles to add depth & volume', '2005-12-13 15:39:14.000000', NULL, 1),
(1947506, 266888, 45933, '<td valign="top">what a great shot! i really like the close up.  It provides the viewer with the fine details.</td>', 'what a great shot! i really like the close up.  It provides the viewer with the fine details.', '2005-12-13 15:40:22.000000', NULL, 1),
(1947538, 267904, 39880, '<td valign="top">I like this one.  Creative use of the canlde.  My only complaint is the top and bottom of the picture.  I think it loses a bit by cutting of the swirl of the flame.</td>', 'I like this one.  Creative use of the canlde.  My only complaint is the top and bottom of the picture.  I think it loses a bit by cutting of the swirl of the flame.', '2005-12-13 15:55:28.000000', NULL, 1),
(1947611, 266891, 3102, '<td valign="top">Whoa.  I''d strongly suggest you try browsing through the FAQs on the site to learn a little more about how to best process an image before submitting it.  This is horribly pixelated, and only 3K (out of 150K you could submit).  Best of luck with future entries :)</td>', 'Whoa.  I''d strongly suggest you try browsing through the FAQs on the site to learn a little more about how to best process an image before submitting it.  This is horribly pixelated, and only 3K (out of 150K you could submit).  Best of luck with future entries :)', '2005-12-13 16:24:59.000000', NULL, 1),
(1947676, 268278, 32754, '<td valign="top">good simple image...great softness, color, and composition...shadows are exquisite.</td>', 'good simple image...great softness, color, and composition...shadows are exquisite.', '2005-12-13 16:48:35.000000', NULL, 1),
(1947714, 267049, 47956, '<td valign="top">An appealing shot, If I could vote I''d go for a 9.</td>', 'An appealing shot, If I could vote I''d go for a 9.', '2005-12-13 16:56:21.000000', NULL, 1),
(1947751, 268063, 40718, '<td valign="top">This is my blue ribbon winner...gorgeous.  Excited to find out the technique.<br/></td>', 'This is my blue ribbon winner...gorgeous.  Excited to find out the technique.', '2005-12-13 17:04:45.000000', NULL, 1),
(1947752, 268278, 40718, '<td valign="top">Lovely, I really enjoyed the few that went with a blue cast instead of a red one.  They really stood out.  9 - one of my top 3</td>', 'Lovely, I really enjoyed the few that went with a blue cast instead of a red one.  They really stood out.  9 - one of my top 3', '2005-12-13 17:05:15.000000', NULL, 1),
(1947756, 267187, 40718, '<td valign="top">Wondeful macro.  That exposure is just perfect.  I''m guessing it''s a bit easier the closer you get to the flame (less dynamic range). 9 - one of my top 3.</td>', 'Wondeful macro.  That exposure is just perfect.  I''m guessing it''s a bit easier the closer you get to the flame (less dynamic range). 9 - one of my top 3.', '2005-12-13 17:05:55.000000', NULL, 1),
(1947762, 266869, 40718, '<td valign="top">great abstract.  Love the gradient fading at the corners and the square crop. 8</td>', 'great abstract.  Love the gradient fading at the corners and the square crop. 8', '2005-12-13 17:07:27.000000', NULL, 1),
(1947765, 268055, 40718, '<td valign="top">creative idea and shadow.  I like the cast too.  The few that were blue/purple in the challenge separated themselves in an interesting way. 8</td>', 'creative idea and shadow.  I like the cast too.  The few that were blue/purple in the challenge separated themselves in an interesting way. 8', '2005-12-13 17:08:10.000000', NULL, 1),
(1947766, 268293, 47117, '<td valign="top">Would have probably been nice for the speed challenge, but I like to see candles in a candlelight challenge. It is hard to take shots of candlelight, and had you given it a try, I would have voted this higher.  Unfortunately, I don''t see the candlelight? Is there a candle in the tree or is that light reflection from another source? If so, let me know.<br/> <br/>PS: Thanks for taking the time to write me with a nice and thoughtful explaination. Because of this, I bumped up your score by 4 more points!  It was well thought out and I like the fact that you contacted me about it to explain the work done.  Sorry to say, my PM isn''t working again from my email, so I am writing this here instead.  My best to you, and have a very lovely holiday season!</td>', 'Would have probably been nice for the speed challenge, but I like to see candles in a candlelight challenge. It is hard to take shots of candlelight, and had you given it a try, I would have voted this higher.  Unfortunately, I don''t see the candlelight? Is there a candle in the tree or is that light reflection from another source? If so, let me know. PS: Thanks for taking the time to write me with a nice and thoughtful explaination. Because of this, I bumped up your score by 4 more points!  It was well thought out and I like the fact that you contacted me about it to explain the work done.  Sorry to say, my PM isn''t working again from my email, so I am writing this here instead.  My best to you, and have a very lovely holiday season!', '2005-12-13 17:08:13.000000', NULL, 1),
(1947775, 267871, 40718, '<td valign="top">Validated?!? Ha. Some people have small imaginations.  Nice effect.  the best is the flame looking like it was "blown" by the bullet.  I''ll be interested in how you got the "path" to be so straight.  That probably took a few attempts. 8</td>', 'Validated?!? Ha. Some people have small imaginations.  Nice effect.  the best is the flame looking like it was "blown" by the bullet.  I''ll be interested in how you got the "path" to be so straight.  That probably took a few attempts. 8', '2005-12-13 17:09:49.000000', NULL, 1),
(1947780, 268091, 40718, '<td valign="top">great lighting and use of the refraction, etc. 8</td>', 'great lighting and use of the refraction, etc. 8', '2005-12-13 17:10:46.000000', NULL, 1),
(1947783, 268173, 40718, '<td valign="top">I love the symmetry of this and the glow of the candles.  I''ll add that someone has some beautiful breasts...but that''s just the man in me talking. 8</td>', 'I love the symmetry of this and the glow of the candles.  I''ll add that someone has some beautiful breasts...but that''s just the man in me talking. 8', '2005-12-13 17:11:37.000000', NULL, 1),
