(1953781, 267904, 26255, '<td valign="top">Very nice.  Did you have someone help you with this.  If this is a self-portrait, you did a great job of holding still while moving the candle.  Either way, nice shot</td>', 'Very nice.  Did you have someone help you with this.  If this is a self-portrait, you did a great job of holding still while moving the candle.  Either way, nice shot', '2005-12-15 11:42:37.000000', NULL, 1),
(1953782, 267927, 26255, '<td valign="top">Nice composition.  It has a very warm "Christmasy" feel.</td>', 'Nice composition.  It has a very warm "Christmasy" feel.', '2005-12-15 11:43:04.000000', NULL, 1),
(1953798, 268297, 26255, '<td valign="top">Nice concept.  Has a very magical feel, but the lighting is a little off.  You have too much light on the side of the model.</td>', 'Nice concept.  Has a very magical feel, but the lighting is a little off.  You have too much light on the side of the model.', '2005-12-15 11:46:45.000000', NULL, 1),
