(1953804, 268257, 26255, '<td valign="top">Very nice!  Creative work!!!</td>', 'Very nice!  Creative work!!!', '2005-12-15 11:49:29.000000', NULL, 1),
(1953912, 267314, 37103, '<td valign="top">The color contrast between the flowers and the candle is beautiful.  It''s too bad the exposure left the actual flame blown out so that you really can''t see any details in the center.</td>', 'The color contrast between the flowers and the candle is beautiful.  It''s too bad the exposure left the actual flame blown out so that you really can''t see any details in the center.', '2005-12-15 12:25:11.000000', NULL, 1),
