(1954967, 267901, 36988, '<td valign="top">beautifully done. In spite of the obvious lighting challenges, you produced a very clear, crisp and warmly inviting image. Ribbon pick here... well done.</td>', 'beautifully done. In spite of the obvious lighting challenges, you produced a very clear, crisp and warmly inviting image. Ribbon pick here... well done.', '2005-12-15 21:00:08.000000', NULL, 1),
(1954970, 267147, 36988, '<td valign="top">An excellent image with alot of personality. A welcomed difference. Well done... :)</td>', 'An excellent image with alot of personality. A welcomed difference. Well done... :)', '2005-12-15 21:01:15.000000', NULL, 1),
(1954975, 268055, 36988, '<td valign="top">Perfectly executed and a definite ribbon pick in my opinion... well done.</td>', 'Perfectly executed and a definite ribbon pick in my opinion... well done.', '2005-12-15 21:02:18.000000', NULL, 1),
(1954980, 268212, 36988, '<td valign="top">You captured a very stirring image with alot of personality and mood. A definite top 10 image with alot of ribbon possibility... well done<br/></td>', 'You captured a very stirring image with alot of personality and mood. A definite top 10 image with alot of ribbon possibility... well done', '2005-12-15 21:03:19.000000', NULL, 1),
