(1954994, 267004, 36988, '<td valign="top">A favorite for this challenge. You really succeeded in delivering a powerfully simple image. May have liked to have seen the flame a little more glowy to enhance the color on the hands but not a big deal... well done<br/></td>', 'A favorite for this challenge. You really succeeded in delivering a powerfully simple image. May have liked to have seen the flame a little more glowy to enhance the color on the hands but not a big deal... well done', '2005-12-15 21:06:02.000000', NULL, 1),
(1955002, 267554, 36988, '<td valign="top">This is such a stirring image... very story bookish with alot of warmth and feeling. well done<br/></td>', 'This is such a stirring image... very story bookish with alot of warmth and feeling. well done', '2005-12-15 21:07:05.000000', NULL, 1),
(1955012, 266325, 36988, '<td valign="top">Very nicely executed. a bit of a tilt but not a big problem... :) good luck with your top 10 image IMO.<br/></td>', 'Very nicely executed. a bit of a tilt but not a big problem... :) good luck with your top 10 image IMO.', '2005-12-15 21:09:59.000000', NULL, 1),
