(1955110, 267453, 46295, '<td valign="top">very erie</td>', 'very erie', '2005-12-15 21:46:09.000000', NULL, 1),
(1955134, 268059, 35321, '<td valign="top">Very nice composition--I like the use of black negative space on top and white below to frame the subject.</td>', 'Very nice composition--I like the use of black negative space on top and white below to frame the subject.', '2005-12-15 21:52:53.000000', NULL, 1),
(1955163, 268144, 35321, '<td valign="top">I like the little flare on the right, it helps balance the subject.   The flame and highlights on the shell casings are somewhat blown-out, maybe exposure bracketing would be helpful.    I like the subtle star effect.</td>', 'I like the little flare on the right, it helps balance the subject.   The flame and highlights on the shell casings are somewhat blown-out, maybe exposure bracketing would be helpful.    I like the subtle star effect.', '2005-12-15 22:07:57.000000', NULL, 1),
(1955172, 267104, 35321, '<td valign="top">Nice red hues in the wine, and I like the rim lighting on the glass.  The almost-but-not-quite symmetry is a little distracting--aesthetically I''d prefer either a more accurate symmetry, or a more obviously asymetric composition.</td>', 'Nice red hues in the wine, and I like the rim lighting on the glass.  The almost-but-not-quite symmetry is a little distracting--aesthetically I''d prefer either a more accurate symmetry, or a more obviously asymetric composition.', '2005-12-15 22:13:26.000000', NULL, 1),
(1955186, 267647, 35321, '<td valign="top">Very nice!  I originally was planning on doing something like this, but this is much better than my attempts.  Nice color gradation, and the curvature of the wicks is perfect.</td>', 'Very nice!  I originally was planning on doing something like this, but this is much better than my attempts.  Nice color gradation, and the curvature of the wicks is perfect.', '2005-12-15 22:21:58.000000', NULL, 1),
